const $=id=>document.getElementById(id);let rows=[],filtered=[],page=0;const PAGE_SIZE=50;
function render(){const start=page*PAGE_SIZE;$('datasetRows').replaceChildren();for(const row of filtered.slice(start,start+PAGE_SIZE)){const tr=document.createElement('tr');for(const i of[0,2,1,3,4,5,6]){const td=document.createElement('td');td.textContent=String(row[i]||'—');tr.append(td);}$('datasetRows').append(tr);}$('datasetStatus').textContent=filtered.length.toLocaleString()+' matching rows';$('pageInfo').textContent=filtered.length?`${start+1}–${Math.min(start+PAGE_SIZE,filtered.length)} of ${filtered.length.toLocaleString()}`:'No matches';$('previous').disabled=page===0;$('next').disabled=start+PAGE_SIZE>=filtered.length;}
function filter(){const q=$('filter').value.normalize('NFKC').toLowerCase().trim(),sheet=$('sheet').value;filtered=rows.filter(row=>(!sheet||row[5]===sheet)&&(!q||row.slice(0,6).some(s=>s.normalize('NFKC').toLowerCase().includes(q))));page=0;render();}
let timer;$('filter').oninput=()=>{clearTimeout(timer);timer=setTimeout(filter,150);};$('sheet').onchange=filter;$('previous').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};
fetch('dataset.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{rows=data.rows;for(const name of new Set(rows.map(r=>r[5]))){const o=document.createElement('option');o.value=name;o.textContent=name;$('sheet').append(o);}filtered=rows;render();}).catch(()=>{$('datasetStatus').textContent='Dataset could not be loaded. Reload the page.';});
